examples.code:
sales = [120 80 45 200 60];
names = {'North', 'South', 'East', 'West', 'Center'};
bubblecloud(sales, names)
title('Sales by region')

bubblechart(1:4, [2 4 1 3], [10 40 20 80]);
bl = bubblelegend('Population');
disp(class(bl))

[X, Y] = meshgrid(-2:0.25:2);
Z = X.^2 + Y.^2;
[C, h] = contour(X, Y, Z, [1 2 3]);
clabel(C, h)

h = animatedline;
addpoints(h, 1:5, (1:5).^2);
[x, y] = getpoints(h);
disp(numel(x))
clearpoints(h)
[x, y] = getpoints(h);
disp(numel(x))

[X, Y, Z] = meshgrid(-2:2);
U = X; V = Y; W = Z;
[cx, cy, cz] = meshgrid(-1:1);
h = coneplot(X, Y, Z, U, V, W, cx, cy, cz);
disp(class(h))
view(3)

[X, Y] = meshgrid(-2:0.1:2);
Z = X.^2 + Y.^2;
[C, h] = contour(X, Y, Z, [1 2 3]);
disp(h.LevelList)
axis equal

[X, Y, Z] = peaks(30);
contour3(X, Y, Z, 12)
view(3)

[X, Y] = meshgrid(-2:2);
Z = X.^2 + Y.^2;
C = contourc(Z, [1 1])

[X, Y, Z] = peaks(40);
contourf(X, Y, Z, 8)
colorbar

rng(1)
V = smooth3(rand(12, 12, 12));
h = contourslice(V, [4 8], [], [6], 5);
view(3)
disp(numel(h) > 0)

[X, Y] = meshgrid(1:4);
cz = curl(X, Y, -Y, X)
cz0 = curl(X, Y, X, Y)

r = [1 1.4 1 0.6 1];
[X, Y, Z] = cylinder(r, 12);
disp(size(X))
disp(Z(:, 1)')
surf(X, Y, Z)

[X, Y, Z] = ellipsoid(1, 0, 0, 2, 1, 3, 10);
disp(size(X))
r = ((X-1)/2).^2 + Y.^2 + (Z/3).^2;
disp(max(abs(r(:) - 1)) < 1e-12)
surf(X, Y, Z)
axis equal
